@spec vm_temper_entry_spec  src=tests/specs/vm_temper_entry_spec.lua  loc=237  cases=6
@exercises tuning (tuning), trackerView (h.vm), editCursor (h.ec), commandManager (h.cmgr)
@surface   tuning.derive, vm:setGridSize, tuning.midiToStep, ec:setPos, vm:editEvent, ec:row, vm:entrySignAt, vm:noteProjection, cmgr:invoke
@harness   mk{seed.notes}

# Intent
  Wired entry under a temperament: drives the real tv:editEvent path
  (not a re-implementation) so the pitch/octave snapping it performs is
  the production wiring. The octave column edits the temper's period-
  cycle octave, keeping the scale step, and rejects octaves a note
  cannot sit on exactly. See docs/tuning.md for the coordinate model.

# Helpers
  @fn mk(harness, temper)  @ 29-40
  @fn lane1(h)  @ 42-46
  @fn pitchStops(col)  @ 50-57
      -- The pitch part spans two cursor stops (note letter, octave digit);
      -- discover them so the test is independent of cellWidth.
  @fn octaveShown(h, temper)  @ 60-64
      -- The octave the cell shows: the period-index octave plus the octaveStep bump.
  @fn rootedNote(harness)  @ 67-82
      -- Places a note at the cursor and returns a typist for its octave stop.

# Cases
  @case 'the octave column negates in place, and the next digit keeps the sign'  [harness]  @ 86-107
  @case 'minus on octave zero arms the sign before the digit lands'  [harness]  @ 111-131
  @case 'a negated octave the note cannot sit on is a no-op'  [harness]  @ 135-146
  @case 'octave column keeps the scale step and sets the period-cycle octave'  [harness]  @ 150-178
  @case 'octave column rejects an octave the note cannot sit on exactly'  [harness]  @ 182-204
  @case 'pitch nudge keeps a note in the addressable range (refuses past the ceiling)'  [harness]  @ 208-235

# Uses (outbound edges)
  @use call tuning.derive  @ 12,21
  @use call vm:setGridSize  @ 38
  @use call tuning.midiToStep  @ 62,162,171
  @use call ec:setPos  @ 74,79,157,166,188,197,214,220
